import {currentMap,TROOPS,clock} from './horizons.js';
const KEY='auralis-frontier-audio-v1',clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
export const AUDIO_DEFAULTS=Object.freeze({master:.65,effects:.7,ambience:.28,music:0,muted:false});
export const SOUND_NAMES=['select','order','confirm','error','wood','stone','metal','water','footstep','motor','naval','bow','gunfire','explosion','energy','coins','complete','alert','bird','cricket','music'];
const noiseBuffers=new WeakMap();
function noise(ctx){if(noiseBuffers.has(ctx))return noiseBuffers.get(ctx);const b=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*2),ctx.sampleRate),d=b.getChannelData(0);let seed=10573,low=0;for(let i=0;i<d.length;i++){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const white=(seed>>>0)/2147483648-1;low=low*.82+white*.18;d[i]=white*.65+low*.35;}noiseBuffers.set(ctx,b);return b;}
// All sound is composed here: layered physical transients, resonances and envelopes.
// No downloaded samples, voices or assets from the reference games are used.
export function renderCue(ctx,name,destination,at=ctx.currentTime,volume=.5,pan=0,variation=.5,onEnd=()=>{}){
 if(!SOUND_NAMES.includes(name))return null;const bus=ctx.createGain(),panner=ctx.createStereoPanner?.(),sources=[],nodes=[bus];bus.gain.value=volume*.52;if(panner){panner.pan.value=clamp(pan,-1,1);bus.connect(panner);panner.connect(destination);nodes.push(panner);}else bus.connect(destination);let duration=0,finished=false;
 function envelope(g,t,d,amp,attack=.004){g.gain.setValueAtTime(.00001,t);g.gain.exponentialRampToValueAtTime(Math.max(.00002,amp),t+attack);g.gain.exponentialRampToValueAtTime(.00001,t+d);}
 function tone(freq,end,d,amp=.3,delay=0,type='sine'){const o=ctx.createOscillator(),g=ctx.createGain(),t=at+delay;o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(12,end),t+d);envelope(g,t,d,amp);o.connect(g);g.connect(bus);o.start(t);o.stop(t+d+.015);sources.push(o);nodes.push(g);duration=Math.max(duration,delay+d+.02);}
 function burst(cutoff,d,amp=.5,delay=0,type='bandpass',q=.7){const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain(),t=at+delay;s.buffer=noise(ctx);f.type=type;f.frequency.setValueAtTime(cutoff,t);f.frequency.exponentialRampToValueAtTime(Math.max(50,cutoff*.45),t+d);f.Q.value=q;envelope(g,t,d,amp,.002);s.connect(f);f.connect(g);g.connect(bus);s.start(t,variation*.8,d+.02);sources.push(s);nodes.push(f,g);duration=Math.max(duration,delay+d+.02);}
 const v=.92+variation*.16;
 if(name==='select'){burst(850,.045,.14);tone(320*v,220,.065,.2);}
 else if(name==='order'){burst(650,.07,.2);tone(190*v,270,.11,.19);tone(380,370,.09,.06,.035);}
 else if(name==='error'){tone(155,110,.19,.25,0,'triangle');tone(210,155,.14,.08,.08);}
 else if(['confirm','complete'].includes(name)){const notes=name==='complete'?[261.63,329.63,392,523.25]:[392,523.25];notes.forEach((f,i)=>{tone(f,f*.998,.42,.21,i*.065,'triangle');tone(f*2.76,f*2.7,.13,.035,i*.065);});burst(2200,.08,.1);}
 else if(name==='wood'){burst(1500*v,.1,.45);tone(175*v,95,.15,.37,0,'triangle');tone(360*v,270,.09,.09,.018);}
 else if(name==='stone'){burst(2600,.12,.5);for(const[f,a]of[[650,.2],[1170,.11],[1780,.055]])tone(f*v,f*.96,.23,a);burst(500,.18,.2,.035,'lowpass');}
 else if(name==='metal'){burst(3100,.07,.35);for(const[f,a]of[[470,.24],[790,.14],[1290,.08],[2150,.025]])tone(f*v,f*.997,.34,a);}
 else if(name==='water'){burst(750,.34,.5,0,'lowpass');for(let i=0;i<3;i++)tone(490+i*180,170+i*80,.12,.12,i*.055);}
 else if(name==='footstep'){burst(420,.09,.55,0,'lowpass');burst(1400,.055,.16,.018);tone(90*v,48,.085,.13);}
 else if(name==='motor'){tone(47*v,44,.42,.14,0,'sawtooth');tone(96,82,.37,.07,.015,'triangle');burst(320,.4,.27,0,'lowpass');for(let i=0;i<3;i++)burst(600,.06,.08,i*.12);}
 else if(name==='naval'){burst(450,.55,.5,0,'lowpass');tone(65,45,.4,.12,0,'triangle');burst(1100,.16,.18,.16);}
 else if(name==='bow'){burst(3200,.07,.35,0,'highpass');tone(230,90,.13,.18,0,'triangle');burst(1200,.05,.15,.14);}
 else if(name==='gunfire'){burst(1600,.12,.78);burst(500,.23,.45,.018,'lowpass');tone(110*v,34,.23,.55);burst(800,.1,.14,.11);}
 else if(name==='explosion'){burst(280,.8,.9,0,'lowpass');burst(1400,.24,.75);tone(85,24,.7,.65);burst(620,.6,.26,.07,'lowpass');}
 else if(name==='energy'){tone(170,850,.18,.13,0,'triangle');tone(560,120,.32,.1,.08);burst(2700,.12,.2);}
 else if(name==='coins'){[1320,1760,2093].forEach((f,i)=>{tone(f,f*.995,.24,.19,i*.055);tone(f*2.4,f*2.38,.11,.025,i*.055);});burst(3900,.035,.14);}
 else if(name==='alert'){[0,.18].forEach(t=>{tone(440,330,.16,.22,t,'triangle');tone(660,495,.16,.07,t);});}
 else if(name==='bird'){[0,.09,.23].forEach((t,i)=>tone(1900+variation*800+i*170,3400+i*150,.065,.12,t));}
 else if(name==='cricket'){for(let i=0;i<4;i++)tone(5100,5200,.025,.06,i*.055);}
 else if(name==='music'){for(const[f,a]of[[1,.3],[2,.08],[3,.025]])tone(196*Math.pow(2,variation/12)*f,(196+variation*130)*f,1.7,a,0,'triangle');}
 let remaining=sources.length;const cleanup=()=>{if(finished)return;finished=true;for(const n of nodes)try{n.disconnect();}catch{}onEnd();};for(const s of sources)s.onended=()=>{if(--remaining<=0)cleanup();};if(!remaining)cleanup();
 return{duration,stop(){for(const s of sources)try{s.stop();}catch{}cleanup();}};
}
export class Soundscape{
 constructor({storage=null,contextFactory=null}={}){this.storage=storage;this.contextFactory=contextFactory;this.prefs={...AUDIO_DEFAULTS};try{const saved=JSON.parse(storage?.getItem(KEY)||'null');if(saved){for(const k of['master','effects','ambience','music'])if(Number.isFinite(saved[k]))this.prefs[k]=clamp(saved[k]);if(typeof saved.muted==='boolean')this.prefs.muted=saved.muted;}}catch{}this.voices=new Set();this.next=new Map();this.previous=new Map();this.metrics={cues:0,peakVoices:0,byName:{}};this.era=0;this.sequence=0;this.paused=false;this.activated=false;this.lastUpdate=0;this.lastBird=0;this.lastMusic=0;}
 async unlock(){if(!this.ctx){try{const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C&&!this.contextFactory)return false;this.ctx=this.contextFactory?this.contextFactory():new C({latencyHint:'interactive'});this.master=this.ctx.createGain();this.effects=this.ctx.createGain();this.ambient=this.ctx.createGain();this.music=this.ctx.createGain();const limiter=this.ctx.createDynamicsCompressor();limiter.threshold.value=-8;limiter.knee.value=8;limiter.ratio.value=8;limiter.attack.value=.003;limiter.release.value=.16;this.effects.connect(this.master);this.ambient.connect(this.master);this.music.connect(this.master);this.master.connect(limiter);limiter.connect(this.ctx.destination);this.limiter=limiter;this.makeAmbience();this.apply();}catch{return false;}}try{if(this.ctx.state==='suspended')await this.ctx.resume();this.activated=this.ctx.state==='running';return this.activated;}catch{return false;}}
 makeAmbience(){const s=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();s.buffer=noise(this.ctx);s.loop=true;f.type='lowpass';f.frequency.value=330;f.Q.value=.4;g.gain.value=.055;s.connect(f);f.connect(g);g.connect(this.ambient);s.start();this.wind={source:s,filter:f,gain:g};}
 apply(){if(!this.ctx)return;const t=this.ctx.currentTime;this.master.gain.setTargetAtTime(this.prefs.muted?0:this.prefs.master,t,.025);this.effects.gain.setTargetAtTime(this.prefs.effects,t,.025);this.ambient.gain.setTargetAtTime(this.prefs.ambience*(this.paused?.28:1),t,.25);this.music.gain.setTargetAtTime(this.prefs.music*(this.paused?.2:1),t,.25);}
 set(key,value){if(!Object.hasOwn(AUDIO_DEFAULTS,key))return false;if(key==='muted')this.prefs[key]=!!value;else{if(!Number.isFinite(Number(value)))return false;this.prefs[key]=clamp(Number(value));}try{this.storage?.setItem(KEY,JSON.stringify(this.prefs));}catch{}this.apply();return true;}
 setPaused(paused){if(this.paused===paused)return;this.paused=paused;this.apply();}
 async visibility(hidden){if(!this.ctx)return;if(hidden){for(const v of [...this.voices])v.stop();try{await this.ctx.suspend();}catch{}}else await this.unlock();}
 play(name,{volume=.6,pan=0,cooldown=.08,group=name,delay=0,music=false,ambient=false,note=null}={}){if(!this.activated||this.ctx?.state!=='running'||this.prefs.muted||!this.prefs.master||!music&&!ambient&&!this.prefs.effects||music&&!this.prefs.music||ambient&&!this.prefs.ambience||this.voices.size>=20)return false;const t=this.ctx.currentTime;if(t<(this.next.get(group)||0))return false;this.next.set(group,t+cooldown);let voice;voice=renderCue(this.ctx,name,music?this.music:ambient?this.ambient:this.effects,t+delay,volume,pan,note??((++this.sequence*37)%101)/100,()=>this.voices.delete(voice));if(!voice)return false;this.voices.add(voice);this.metrics.cues++;this.metrics.byName[name]=(this.metrics.byName[name]||0)+1;this.metrics.peakVoices=Math.max(this.metrics.peakVoices,this.voices.size);return true;}
 result(ok){this.play(ok?'confirm':'error',{volume:ok?.2:.45,cooldown:.15});}
 preview(){this.unlock().then(ok=>{if(!ok)return;['wood','stone','water','metal','gunfire','complete'].forEach((name,i)=>this.play(name,{volume:.48,delay:i*.22,group:'preview-'+i,cooldown:0}));});}
 at(name,r,x,y,volume=.6){const m=r.map;if(!m?.sight?.[Math.floor(y)*m.size+Math.floor(x)]||!r.onScreen(x,y,30))return false;const p=r.groundPoint(x,y),d=Math.hypot(p.x-r.w*.5,p.y-r.h*.5)/Math.max(r.w,r.h);return this.play(name,{volume:volume*clamp(1-d*.8,.1,1),pan:clamp((p.x/r.w-.5)*1.5,-.85,.85),group:name,cooldown:name==='footstep'?.16:.1});}
 update(state,r,shots=[]){if(!this.activated)return;const m=currentMap(state);this.era=state.era;for(const s of shots){const name=['archer','spearman','cavalry'].includes(s.kind)?'bow':['missile','bulwark','gunboat'].includes(s.kind)?'explosion':['wasp','arcanist','golem','drake'].includes(s.kind)?'energy':'gunfire';this.at(name,r,s.x,s.y,name==='explosion'?.5:.48);}
  const now=this.ctx.currentTime;if(now-this.lastUpdate<.12)return;this.lastUpdate=now;const first=this.mapId!==m.id;if(first){this.previous.clear();this.nextUnit=new Map();this.mapId=m.id;this.initialized=false;}this.nextUnit??=new Map();let count=0;
  for(const u of m.units){if(u.hp<=0||u.embarked||u.inTransit||u.depth!==(r.layer||0))continue;const spec=TROOPS[u.type];if(!first&&this.initialized&&!this.previous.has(u.id))this.at('complete',r,u.x,u.y,.45);this.previous.set(u.id,true);const key=u.id+':delivery',delivery=u.lastDelivery?.time;if(delivery&&this.previous.has(key)&&delivery!==this.previous.get(key))this.at('coins',r,u.x,u.y,.24);this.previous.set(key,delivery);
   if(count>=4||now<(this.nextUnit.get(u.id)||0))continue;const work=['gather','dig','construct','upgrade','project','operate','survey','study','infrastructure'].includes(u.order.kind)&&!u.walking;let name=null;if(u.walking)name=spec.naval?'naval':spec.logistic||['jeep','bulwark','missile','mecha'].includes(u.type)?'motor':spec.flying?'energy':'footstep';else if(work)name=u.gatherResource==='water'||['well','waterworks'].includes(m.buildings.find(b=>b.id===u.order.target)?.type)?'water':u.order.kind==='gather'&&u.gatherResource!=='wood'&&u.gatherResource!=='food'||u.order.kind==='dig'?'stone':u.order.kind==='operate'&&state.era>=12?'metal':'wood';if(name&&this.at(name,r,u.x,u.y,name==='footstep'?.23:.3)){count++;this.nextUnit.set(u.id,now+(name==='footstep'?.55:name==='motor'?1.2:name==='naval'?1.5:1.1));}}
  for(const b of m.buildings){const key='building:'+b.id,signature=b.progress>=1?b.level+':'+b.tier:'work',old=this.previous.get(key);if(!first&&old&&signature!=='work'&&old!==signature)this.at('complete',r,b.x,b.y,.65);this.previous.set(key,signature);}
  for(const e of state.events){if(e.map!==m.id)continue;const key='event:'+e.id;if(!first&&!this.previous.has(key))this.play('alert',{volume:.4,cooldown:1});this.previous.set(key,true);if(e.starts<=state.time&&e.radius&&now>=(this.next.get('hazard')||0)&&['quake','meteor','tornado','tsunami','seaquake'].includes(e.type))if(this.at('explosion',r,e.x,e.y,.35))this.next.set('hazard',now+6);}
  if(this.previous.size>10000)this.previous.clear();if(this.nextUnit.size>2500)this.nextUnit.clear();const night=clock(state).night;
  if(now>=this.lastBird){this.lastBird=now+(night?11:8);this.play(night?'cricket':'bird',{volume:night?.25:.35,pan:Math.sin(now*.2)*.65,ambient:true,cooldown:1});}
  if(now>=this.lastMusic&&this.prefs.music){this.lastMusic=now+1.8;const steps=[0,2,4,7,9,7,4,2],n=steps[Math.floor(now/1.8)%steps.length];this.play('music',{volume:.19,pan:Math.sin(now*.1)*.35,music:true,group:'score',cooldown:1,note:n});}
  this.wind.filter.frequency.setTargetAtTime(night?230:330,now,.5);this.wind.gain.gain.setTargetAtTime(.045+Math.sin(now*.08)*.008,now,.5);this.initialized=true;
 }
 dispose(){for(const v of [...this.voices])v.stop();try{this.wind?.source.stop();}catch{}this.ctx?.close();this.activated=false;}
}
let storage;try{storage=globalThis.localStorage;}catch{storage=null;}
export const sound=new Soundscape({storage});
export function audioSettings(){const p=sound.prefs;return `<section class="audio-settings" aria-label="Sonido"><div class="audio-heading"><h3>Sonido del mundo</h3><label><input id="audio-muted" type="checkbox" ${p.muted?'checked':''}> Silenciar</label></div><p>Sonidos originales de trabajo, movimiento y combate. Se activan al tocar el juego.</p><div class="audio-sliders">${[['master','Volumen general'],['effects','Efectos y acciones'],['ambience','Ambiente natural'],['music','Música suave · opcional']].map(([key,name])=>`<label for="audio-${key}"><span>${name}<output id="audio-${key}-value">${Math.round(p[key]*100)}%</output></span><input id="audio-${key}" data-audio-pref="${key}" type="range" min="0" max="100" value="${Math.round(p[key]*100)}"></label>`).join('')}</div><button data-action="audio-preview">Probar sonidos</button></section>`;}
